export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export enum GameState {
  WELCOME = 'WELCOME',
  PLAYING = 'PLAYING',
  VICTORY = 'VICTORY',
  GAME_OVER = 'GAME_OVER' // Not strictly used based on prompt logic, but good to have
}

export interface TriviaQuestion {
  questionText: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
}

export interface GameStatus {
  state: GameState;
  difficulty: Difficulty;
  genre: string;
  score: number;
  streak: number;
}

import { Difficulty } from "./types";

export const GENRES = [
  "General Knowledge",
  "Science & Nature",
  "History",
  "Technology",
  "Movies & TV",
  "Music",
  "Geography",
  "Video Games"
];

export const DIFFICULTY_COLORS = {
  [Difficulty.EASY]: "text-emerald-400 bg-emerald-400/10 border-emerald-400/20",
  [Difficulty.MEDIUM]: "text-amber-400 bg-amber-400/10 border-amber-400/20",
  [Difficulty.HARD]: "text-rose-500 bg-rose-500/10 border-rose-500/20"
};

export const DIFFICULTY_LABELS = {
  [Difficulty.EASY]: "Easy",
  [Difficulty.MEDIUM]: "Medium",
  [Difficulty.HARD]: "Hard"
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Difficulty, TriviaQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questionText: {
      type: Type.STRING,
      description: "The trivia question text."
    },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of 4 possible answers.",
    },
    correctAnswer: {
      type: Type.STRING,
      description: "The correct answer from the options list.",
    },
    explanation: {
      type: Type.STRING,
      description: "A brief interesting fact explaining the answer.",
    }
  },
  required: ["questionText", "options", "correctAnswer", "explanation"],
};

export const generateTriviaQuestion = async (genre: string, difficulty: Difficulty): Promise<TriviaQuestion> => {
  const model = "gemini-2.5-flash";

  const prompt = `
    Generate a ${difficulty.toLowerCase()} difficulty trivia question about "${genre}".

    Difficulty Guidelines:
    - Easy: Common knowledge, widely known facts.
    - Medium: Requires specific knowledge but not obscure.
    - Hard: Obscure facts, precise dates, or specific details experts might know.

    Ensure there are exactly 4 options.
    Ensure the correct answer is included in the options.
    Do not mention the difficulty level in the question text.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        temperature: 0.7, // Add some variety
      },
    });

    const text = response.text;
    if (!text) {
        throw new Error("Empty response from Gemini");
    }

    const data = JSON.parse(text) as TriviaQuestion;

    // Shuffle options to ensure the correct answer isn't always in the same spot (though Gemini usually randomizes, it's safer to do it here too if needed, but for now we trust the JSON structure)
    return data;
  } catch (error) {
    console.error("Error generating question:", error);
    // Fallback question to prevent app crash
    return {
      questionText: "We encountered an error contacting the trivia master. Which of these is a retry button?",
      options: ["Retry", "Cancel", "Ignore", "Abort"],
      correctAnswer: "Retry",
      explanation: "Sometimes API calls fail. Please try again."
    };
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-6 py-3 rounded-xl font-semibold transition-all duration-200 active:scale-95 disabled:opacity-50 disabled:pointer-events-none";

  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/30 border border-indigo-400/20",
    secondary: "bg-slate-700 hover:bg-slate-600 text-white border border-slate-500/30",
    outline: "bg-transparent border-2 border-slate-600 hover:border-indigo-400 text-slate-300 hover:text-white",
    ghost: "bg-transparent hover:bg-white/5 text-slate-400 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

