                }
              }}
            />
            <button
              onClick={() => customGenreInput.trim() && startGame(customGenreInput)}
              disabled={!customGenreInput.trim()}
              className="px-6 py-3 rounded-xl bg-slate-700 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg active:scale-95 whitespace-nowrap"
            >
              Start Custom
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderGame = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">

      {/* Header */}
      <div className="w-full flex justify-between items-center mb-8 bg-slate-900/40 p-4 rounded-2xl border border-slate-800/50 backdrop-blur-md">
        <button onClick={restartGame} className="text-sm font-medium text-slate-500 hover:text-white transition-colors flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Abort
        </button>

        <div className="flex items-center space-x-4">
           {/* Audio Toggle */}
           <button 
             onClick={toggleMute} 
             className={`p-2 rounded-full transition-colors ${isMuted ? 'text-slate-600 hover:text-slate-400' : 'text-indigo-400 hover:text-indigo-300 bg-indigo-400/10'}`}
             title={isMuted ? "Unmute Host" : "Mute Host"}
           >
             {isMuted ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
                </svg>
             ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                </svg>
