export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES, DIFFICULTY_COLORS } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Custom Genre Input State
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  // Turn State
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');

  // History State (persisted in localStorage)
  const [history, setHistory] = useState<string[]>([]);

  // Audio State
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);

  // Initialize Audio Context lazily
  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopAudio = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Ignore errors if already stopped
      }
      currentSourceRef.current = null;
    }
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const pcm16 = new Int16Array(bytes.buffer);
      const sampleRate = 24000; // Gemini TTS default sample rate

      // Create buffer with the correct sample rate
      const buffer = ctx.createBuffer(1, pcm16.length, sampleRate);
      const channelData = buffer.getChannelData(0);

      for (let i = 0; i < pcm16.length; i++) {
          // Normalize 16-bit integer to float [-1.0, 1.0]
          channelData[i] = pcm16[i] / 32768.0;
      }

      return buffer;
  };

  const playAudio = async (base64Data: string) => {
    if (isMuted) return;

    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      stopAudio();

      // Decode raw PCM data manually instead of using decodeAudioData which expects headers
      const buffer = decodePCM(base64Data, ctx);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
    }
  };

  const speak = useCallback(async (text: string) => {
    if (isMuted) return;
    const audioData = await generateTriviaAudio(text);
    if (audioData) {
      playAudio(audioData);
    }
  }, [isMuted]);

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('trivia_history');
    if (saved) {
        try {
            setHistory(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to parse history", e);
        }
    }
  }, []);

  // Update history helper
  const addToHistory = (newQuestionText: string) => {
    setHistory(prev => {
        // Keep only the last 100 questions to maintain context window efficiency
        const newHistory = [newQuestionText, ...prev].slice(0, 100);
        localStorage.setItem('trivia_history', JSON.stringify(newHistory));
        return newHistory;
    });
  };

  // Auto-narrate question when it loads
  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      // Small delay to ensure smooth transition
      const timer = setTimeout(() => {
         speak(question.questionText);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading, speak]);

  // Auto-narrate result when answer revealed
  useEffect(() => {
    if (isAnswerRevealed && question) {
      const prefix = selectedOption === question.correctAnswer ? "Correct!" : "Incorrect.";
      const textToSpeak = `${prefix} ${question.explanation}`;
      speak(textToSpeak);
    }
  }, [isAnswerRevealed, selectedOption, question, speak]);

  // Fetch a new question based on current state
  const fetchQuestion = useCallback(async (targetDifficulty: Difficulty, targetGenre: string) => {
    stopAudio(); // Stop any previous speech
    setLoading(true);
    setQuestion(null);
    setSelectedOption(null);
    setIsAnswerRevealed(false);
    setFeedbackMessage('');

    try {
      // Pass the current history to the service to avoid repetitions
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, history);
      setQuestion(newQuestion);

      // Add valid questions to history
      if (newQuestion && newQuestion.questionText && !newQuestion.questionText.includes("error")) {
        addToHistory(newQuestion.questionText);
      }
    } catch (error) {
      console.error("Failed to fetch question", error);
    } finally {
      setLoading(false);
    }
  }, [history]); // Re-create fetchQuestion when history changes

  // Handle Answer Selection
  const handleAnswer = (option: string) => {
    if (isAnswerRevealed || !question) return;

    stopAudio(); // Stop reading question if user answers quickly
    setSelectedOption(option);
    setIsAnswerRevealed(true);

    const isCorrect = option === question.correctAnswer;

    if (isCorrect) {
      setFeedbackMessage("Correct! Promoting...");
      // Delay before moving to next state
      setTimeout(() => {
        handleProgression(true);
      }, 4000); // Increased delay to allow speech to finish (mostly)
    } else {
      setFeedbackMessage("Incorrect. Demoting...");
      setTimeout(() => {
        handleProgression(false);
      }, 4500); // Increased delay to allow explanation reading
    }
  };

  // Progression Logic
  const handleProgression = (isCorrect: boolean) => {
    if (isCorrect) {
      switch (difficulty) {
        case Difficulty.EASY:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.HARD);
          fetchQuestion(Difficulty.HARD, genre);
          break;
        case Difficulty.HARD:
          setGameState(GameState.VICTORY);
          break;
      }
    } else {
      // Incorrect Answer Logic
      switch (difficulty) {
        case Difficulty.HARD:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.EASY);
          fetchQuestion(Difficulty.EASY, genre);
          break;
        case Difficulty.EASY:
          // Stay on Easy
          fetchQuestion(Difficulty.EASY, genre);
          break;
      }
    }
  };

  const startGame = (selectedGenre: string) => {
    // Initialize audio context on user gesture
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    fetchQuestion(Difficulty.EASY, selectedGenre);
  };

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setCustomGenreInput('');
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
