import { DifficultyBadge } from './components/DifficultyBadge';

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Custom Genre Input State
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  // Turn State
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isCorrect, setIsCorrect] = useState<boolean>(false);

  // History State (persisted in localStorage)
  const [history, setHistory] = useState<string[]>([]);

  // Audio State
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize Audio Context lazily
  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopCurrentSource = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Ignore errors if already stopped
      }
      currentSourceRef.current = null;
    }
  };

  const stopAudio = () => {
    // Invalidate any pending async tasks that might try to play audio later
    audioRequestIdRef.current += 1;
    stopCurrentSource();
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const pcm16 = new Int16Array(bytes.buffer);
      const sampleRate = 24000; // Gemini TTS default sample rate

      // Create buffer with the correct sample rate
      const buffer = ctx.createBuffer(1, pcm16.length, sampleRate);
      const channelData = buffer.getChannelData(0);

      for (let i = 0; i < pcm16.length; i++) {
          // Normalize 16-bit integer to float [-1.0, 1.0]
          channelData[i] = pcm16[i] / 32768.0;
      }

      return buffer;
  };

  const playAudio = async (base64Data: string) => {
    if (isMuted) return;

    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      stopCurrentSource();

      // Decode raw PCM data manually instead of using decodeAudioData which expects headers
      const buffer = decodePCM(base64Data, ctx);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
    }
  };

  const speak = useCallback(async (text: string) => {
    if (isMuted) return;

    // Increment ID to cancel any pending previous requests
    stopAudio();
    const myRequestId = audioRequestIdRef.current;

    const audioData = await generateTriviaAudio(text);

    // If the ID has changed since we started, it means stopAudio() or speak() 
    // was called again (e.g. user moved to next question). We should abandon this audio.
    if (audioRequestIdRef.current !== myRequestId) {
        return;
    }

    if (audioData) {
      playAudio(audioData);
    }
  }, [isMuted]);

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('trivia_history');
    if (saved) {
        try {
            setHistory(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to parse history", e);
        }
    }
  }, []);

  // Update history helper
  const addToHistory = (newQuestionText: string) => {
    setHistory(prev => {
        // Keep only the last 100 questions to maintain context window efficiency
        const newHistory = [newQuestionText, ...prev].slice(0, 100);
        localStorage.setItem('trivia_history', JSON.stringify(newHistory));
        return newHistory;
    });
  };

  // Auto-narrate question when it loads
  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      // Small delay to ensure smooth transition
      const timer = setTimeout(() => {
         speak(question.questionText);
         // Focus input on new question
         if (inputRef.current) {
            inputRef.current.focus();
         }
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading, speak]);

  // Auto-narrate result when answer revealed
  useEffect(() => {
    if (isAnswerRevealed && question) {
      const prefix = isCorrect ? "Correct!" : `Incorrect. The answer is ${question.correctAnswer}.`;
      const textToSpeak = `${prefix} ${question.explanation}`;
      speak(textToSpeak);
    }
  }, [isAnswerRevealed, isCorrect, question, speak]);

  // Fetch a new question based on current state
  const fetchQuestion = useCallback(async (targetDifficulty: Difficulty, targetGenre: string) => {
    stopAudio(); // Stop any previous speech
    setLoading(true);
    setQuestion(null);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setFeedbackMessage('');
    setIsCorrect(false);

    try {
      // Pass the current history to the service to avoid repetitions
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, history);
      setQuestion(newQuestion);

      // Add valid questions to history
      if (newQuestion && newQuestion.questionText && !newQuestion.questionText.includes("error")) {
        addToHistory(newQuestion.questionText);
      }
    } catch (error) {
      console.error("Failed to fetch question", error);
    } finally {
      setLoading(false);
    }
  }, [history]); 

  // Normalize string for fuzzy matching (remove punctuation, lower case, trim)
  const normalizeAnswer = (str: string) => {
    return str.toLowerCase().replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ").trim();
  };

  const handleSubmitAnswer = () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    stopAudio(); // Stop reading question
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = normalizeAnswer(userAnswer);
    const match = question.acceptedAnswers.some(ans => normalizeAnswer(ans) === normalizedUserAnswer);

    setIsCorrect(match);

    if (match) {
      setFeedbackMessage("Correct! Promoting...");
      setTimeout(() => {
        handleProgression(true);
      }, 4000); 
    } else {
      setFeedbackMessage("Incorrect. Demoting...");
      setTimeout(() => {
        handleProgression(false);
      }, 4500);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSubmitAnswer();
    }
  };

  // Progression Logic
  const handleProgression = (userCorrect: boolean) => {
    if (userCorrect) {
      switch (difficulty) {
        case Difficulty.EASY:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.HARD);
          fetchQuestion(Difficulty.HARD, genre);
          break;
        case Difficulty.HARD:
          setGameState(GameState.VICTORY);
          break;
      }
    } else {
      // Incorrect Answer Logic
      switch (difficulty) {
        case Difficulty.HARD:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.EASY);
          fetchQuestion(Difficulty.EASY, genre);
          break;
        case Difficulty.EASY:
          // Stay on Easy
          fetchQuestion(Difficulty.EASY, genre);
          break;
      }
    }
  };

  const startGame = (selectedGenre: string) => {
    // Initialize audio context on user gesture
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    fetchQuestion(Difficulty.EASY, selectedGenre);
  };

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setCustomGenreInput('');
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (!isMuted) {
      stopAudio();
    }
  };

  // Render Methods
  const renderWelcome = () => (
    <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 drop-shadow-lg">
          ASCENSION
        </h1>
        <p className="text-xl text-slate-300 font-light tracking-wide">
          Prove your worth. Ascend to victory.
        </p>
      </div>

      <div className="w-full glass-panel p-8 rounded-3xl shadow-2xl shadow-indigo-900/20">
        <h2 className="text-2xl font-semibold mb-6 text-white">Select Your Realm</h2>

        {/* Predefined Genres */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {GENRES.map((g) => (
            <button
              key={g}
              onClick={() => startGame(g)}
              className="group relative p-4 rounded-xl bg-slate-800/50 hover:bg-indigo-600/20 border border-slate-700 hover:border-indigo-400 transition-all duration-300 overflow-hidden"
            >
              <span className="relative z-10 font-medium text-slate-200 group-hover:text-white transition-colors">{g}</span>
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/0 to-purple-600/0 group-hover:from-indigo-600/10 group-hover:to-purple-600/20 transition-all duration-300"></div>
            </button>
          ))}
          <button
              onClick={() => startGame("General Knowledge")}
              className="col-span-2 md:col-span-4 mt-2 p-4 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold tracking-wider shadow-lg shadow-indigo-900/40 transition-all active:scale-95"
            >
              SURPRISE ME (RANDOM)
          </button>
        </div>

        {/* Custom Genre Input */}
        <div className="pt-8 border-t border-slate-700/50">
          <p className="text-slate-400 text-sm mb-4 uppercase tracking-widest font-semibold">Or forge your own path</p>
          <div className="flex flex-col md:flex-row gap-3">
            <input
              type="text"
              value={customGenreInput}
              onChange={(e) => setCustomGenreInput(e.target.value)}
              placeholder="E.g., 90s Hip Hop, Quantum Physics, Cheese..."
              className="flex-1 bg-slate-800/50 border border-slate-600 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && customGenreInput.trim()) {
                  startGame(customGenreInput);
                }
              }}
            />
            <button
              onClick={() => customGenreInput.trim() && startGame(customGenreInput)}
              disabled={!customGenreInput.trim()}
              className="px-6 py-3 rounded-xl bg-slate-700 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg active:scale-95 whitespace-nowrap"
            >
              Start Custom
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderGame = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">

      {/* Header */}
      <div className="w-full flex justify-between items-center mb-8 bg-slate-900/40 p-4 rounded-2xl border border-slate-800/50 backdrop-blur-md">
        <button onClick={restartGame} className="text-sm font-medium text-slate-500 hover:text-white transition-colors flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Abort
        </button>

        <div className="flex items-center space-x-4">
           {/* Audio Toggle */}
           <button 
             onClick={toggleMute} 
             className={`p-2 rounded-full transition-colors ${isMuted ? 'text-slate-600 hover:text-slate-400' : 'text-indigo-400 hover:text-indigo-300 bg-indigo-400/10'}`}
             title={isMuted ? "Unmute Host" : "Mute Host"}
           >
             {isMuted ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
                </svg>
             ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                </svg>
             )}
           </button>
           <DifficultyBadge difficulty={difficulty} />
        </div>
      </div>

      {loading ? (
        <LoadingSpinner />
      ) : question ? (
        <div className="w-full space-y-8 animate-[fadeIn_0.5s_ease-out]">

          {/* Question Card */}
          <div className="glass-panel p-8 rounded-3xl shadow-2xl relative overflow-hidden">
             {/* Progress bar background hint */}
             <div className={`absolute top-0 left-0 h-1 w-full ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'} opacity-30`}></div>

             <div className="space-y-2 mb-2">
                <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">{genre}</span>
             </div>
             <h2 className="text-2xl md:text-3xl font-bold leading-tight text-white mb-6">
              {question.questionText}
            </h2>

            {/* Answer Input */}
            <div className="flex flex-col md:flex-row gap-3">
              <input
                ref={inputRef}
                type="text"
                value={userAnswer}
                onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isAnswerRevealed}
                placeholder="Type your answer..."
                autoComplete="off"
                className={`flex-1 bg-slate-900/50 border-2 rounded-xl px-5 py-4 text-xl text-white placeholder-slate-500 focus:outline-none transition-all ${
                  isAnswerRevealed
                    ? isCorrect
                      ? 'border-emerald-500 bg-emerald-900/20'
                      : 'border-rose-500 bg-rose-900/20'
                    : 'border-slate-600 focus:border-indigo-500 focus:shadow-[0_0_15px_rgba(99,102,241,0.3)]'
                }`}
              />
              <Button 
                onClick={handleSubmitAnswer}
                disabled={!userAnswer.trim() || isAnswerRevealed}
                className="whitespace-nowrap md:w-auto"
              >
                Submit
              </Button>
            </div>
          </div>

          {/* Feedback / Explanation Panel */}
          {isAnswerRevealed && (
            <div className={`mt-6 p-6 rounded-2xl glass-panel border-l-4 ${isCorrect ? 'border-emerald-500' : 'border-rose-500'} animate-[slideUp_0.3s_ease-out]`}>
              <div className="flex items-center space-x-3 mb-2">
                 <span className={`font-bold ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isCorrect ? 'Correct!' : 'Incorrect'}
                 </span>
                 {!isCorrect && (
                   <span className="text-slate-300">
                     The answer was: <span className="font-bold text-white">{question.correctAnswer}</span>
                   </span>
                 )}
                 <span className="text-slate-500">|</span>
                 <span className="text-slate-400 text-sm">Next question loading...</span>
              </div>
              <p className="text-slate-200 leading-relaxed mt-3">
                {question.explanation}
              </p>
            </div>
          )}

        </div>
      ) : null}
    </div>
  );

  const renderVictory = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
      <div className="glass-panel p-10 md:p-16 rounded-[3rem] shadow-2xl shadow-indigo-500/20 max-w-2xl border-indigo-500/30 animate-[zoomIn_0.5s_ease-out]">
        <div className="mb-8 inline-block p-4 rounded-full bg-indigo-500/20 text-indigo-300 mb-6">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
           </svg>
        </div>
        <h1 className="text-5xl md:text-7xl font-black text-white mb-6 tracking-tight">
          VICTORY
        </h1>
        <p className="text-xl md:text-2xl text-slate-300 mb-10 leading-relaxed">
          You have conquered the <span className="text-indigo-400 font-bold">Hard</span> difficulty and proven your intellect in the realm of {genre}.
        </p>
        <Button onClick={restartGame} variant="primary" className="text-lg px-10 py-4 shadow-indigo-500/50 hover:shadow-indigo-500/80">
          Play Again
        </Button>
      </div>
    </div>
  );

  // Background Elements
  const Background = () => (
    <div className="fixed inset-0 z-0">
       <div className="absolute inset-0 bg-slate-950"></div>
       <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-indigo-950 via-slate-950 to-slate-950 opacity-80"></div>
       <div className="absolute top-[-20%] right-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/20 blur-[120px]"></div>
       <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px]"></div>
    </div>
  );

  return (
    <div className="relative w-full min-h-screen font-sans">
      <Background />
      {gameState === GameState.WELCOME && renderWelcome()}
      {gameState === GameState.PLAYING && renderGame()}
      {gameState === GameState.VICTORY && renderVictory()}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { Difficulty, TriviaQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questionText: {
      type: Type.STRING,
      description: "The trivia question text. It should be answerable with a short phrase or single word."
    },
    acceptedAnswers: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of valid answers. Include synonyms, abbreviations, and common spelling variations (e.g. ['US', 'USA', 'United States']).",
    },
    correctAnswer: {
      type: Type.STRING,
      description: "The primary correct answer to display to the user.",
    },
    explanation: {
      type: Type.STRING,
      description: "A brief interesting fact explaining the answer.",
    }
  },
  required: ["questionText", "acceptedAnswers", "correctAnswer", "explanation"],
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateTriviaQuestion = async (
  genre: string, 
  difficulty: Difficulty, 
  previousQuestions: string[] = []
): Promise<TriviaQuestion> => {
  const model = "gemini-2.5-flash";

  // Create a robust prompt that enforces variety
  const prompt = `
    Generate a ${difficulty.toLowerCase()} difficulty open-ended trivia question about "${genre}".

    Difficulty Guidelines:
    - Easy: Common knowledge, single word answers.
    - Medium: Requires specific knowledge, short phrase answers.
    - Hard: Obscure facts, specific names or dates.

    Constraints:
    - The answer must be concise (1-4 words ideally).
    - Provide multiple acceptable variations for the answer in 'acceptedAnswers'.
    - Do not mention the difficulty level in the question text.

    CRITICAL INSTRUCTIONS FOR VARIETY:
    1. Select a random sub-topic or specific niche within "${genre}" before generating the question.
    2. AVOID DUPLICATION: Do not generate questions that are identical or very similar to these recent user questions:
       ${JSON.stringify(previousQuestions)}
  `;

  let lastError: any;

  // Retry loop for robustness (3 attempts)
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: questionSchema,
          temperature: 0.8, 
        },
      });

      const text = response.text;
      if (!text) {
          throw new Error("Empty response from Gemini");
      }

      const data = JSON.parse(text) as TriviaQuestion;
      return data;
    } catch (error: any) {
      console.error(`Attempt ${attempt} failed:`, error);
      lastError = error;

      // If it's a 429 (Too Many Requests) or 503 (Service Unavailable), wait and retry
      if (attempt < 3) {
        // Exponential backoff: 1s, 2s, 4s...
        await delay(1000 * Math.pow(2, attempt - 1));
      }
    }
  }

  // If we get here, all retries failed
  console.error("All attempts to generate question failed.", lastError);

  // Try to extract a meaningful message
  let errorMessage = "Sometimes API calls fail. Please try again.";
  if (lastError?.message?.includes("429")) {
    errorMessage = "We're receiving too many requests. Please wait a moment.";
  }

  return {
    questionText: `System Error: ${lastError?.message || "Unknown error"}. Please type 'retry' to continue.`,
    acceptedAnswers: ["retry"],
    correctAnswer: "retry",
    explanation: errorMessage
  };
};

export const generateTriviaAudio = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
            voiceConfig: {
              // Fenrir is a deep, authoritative voice suitable for a game show host
              prebuiltVoiceConfig: { voiceName: 'Fenrir' },
            },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio || null;
  } catch (error) {
    console.error("Audio generation failed:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES, DIFFICULTY_COLORS } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

interface LastTurnResult {
  isCorrect: boolean;
  correctAnswer: string;
  explanation: string;
}

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Custom Genre Input State
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  // Turn State
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isCorrect, setIsCorrect] = useState<boolean>(false);

  // Persistent Feedback State
  const [lastTurnResult, setLastTurnResult] = useState<LastTurnResult | null>(null);

  // History State (persisted in localStorage)
  const [history, setHistory] = useState<string[]>([]);

  // Audio State
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize Audio Context lazily
  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopCurrentSource = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Ignore errors if already stopped
      }
      currentSourceRef.current = null;
    }
  };

  const stopAudio = () => {
    // Invalidate any pending async tasks that might try to play audio later
    audioRequestIdRef.current += 1;
    stopCurrentSource();
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const pcm16 = new Int16Array(bytes.buffer);
      const sampleRate = 24000; // Gemini TTS default sample rate

      // Create buffer with the correct sample rate
      const buffer = ctx.createBuffer(1, pcm16.length, sampleRate);
      const channelData = buffer.getChannelData(0);

      for (let i = 0; i < pcm16.length; i++) {
          // Normalize 16-bit integer to float [-1.0, 1.0]
          channelData[i] = pcm16[i] / 32768.0;
      }

      return buffer;
  };

  const playAudio = async (base64Data: string) => {
    if (isMuted) return;

    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      stopCurrentSource();

      // Decode raw PCM data manually instead of using decodeAudioData which expects headers
      const buffer = decodePCM(base64Data, ctx);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
    }
  };

  const speak = useCallback(async (text: string) => {
    if (isMuted) return;

    // Increment ID to cancel any pending previous requests
    stopAudio();
    const myRequestId = audioRequestIdRef.current;

    const audioData = await generateTriviaAudio(text);

    // If the ID has changed since we started, it means stopAudio() or speak() 
    // was called again (e.g. user moved to next question). We should abandon this audio.
    if (audioRequestIdRef.current !== myRequestId) {
        return;
    }

    if (audioData) {
      playAudio(audioData);
    }
  }, [isMuted]);

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('trivia_history');
    if (saved) {
        try {
            setHistory(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to parse history", e);
        }
    }
  }, []);

  // Update history helper
  const addToHistory = (newQuestionText: string) => {
    setHistory(prev => {
        // Keep only the last 100 questions to maintain context window efficiency
        const newHistory = [newQuestionText, ...prev].slice(0, 100);
        localStorage.setItem('trivia_history', JSON.stringify(newHistory));
        return newHistory;
    });
  };

  // Auto-narrate question when it loads
  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      // Small delay to ensure smooth transition
      const timer = setTimeout(() => {
         speak(question.questionText);
         // Focus input on new question
         if (inputRef.current) {
            inputRef.current.focus();
         }
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading, speak]);

  // Auto-narrate result when answer revealed
  useEffect(() => {
    if (isAnswerRevealed && question) {
      const prefix = isCorrect ? "Correct!" : `Incorrect. The answer is ${question.correctAnswer}.`;
      const textToSpeak = `${prefix} ${question.explanation}`;
      speak(textToSpeak);
    }
  }, [isAnswerRevealed, isCorrect, question, speak]);

  // Fetch a new question based on current state
  const fetchQuestion = useCallback(async (targetDifficulty: Difficulty, targetGenre: string) => {
    // stopAudio(); // Don't stop audio here immediately to allow explanation to finish if it's playing during load
    setLoading(true);
    setQuestion(null);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setFeedbackMessage('');
    setIsCorrect(false);

    try {
      // Pass the current history to the service to avoid repetitions
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, history);
      setQuestion(newQuestion);

      // Add valid questions to history
      if (newQuestion && newQuestion.questionText && !newQuestion.questionText.includes("error")) {
        addToHistory(newQuestion.questionText);
      }
    } catch (error) {
      console.error("Failed to fetch question", error);
    } finally {
      setLoading(false);
    }
  }, [history]); 

  // Normalize string for fuzzy matching (remove punctuation, lower case, trim)
  const normalizeAnswer = (str: string) => {
    return str.toLowerCase().replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ").trim();
  };

  const handleSubmitAnswer = () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    // Clear previous persistent feedback when submitting a new answer
    setLastTurnResult(null);

    stopAudio(); // Stop reading question
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = normalizeAnswer(userAnswer);
    const match = question.acceptedAnswers.some(ans => normalizeAnswer(ans) === normalizedUserAnswer);

    setIsCorrect(match);

    if (match) {
      setFeedbackMessage("Correct! Promoting...");
      // Reduced delay to make game snappier since we show result in next screen
      setTimeout(() => {
        handleProgression(true);
      }, 1500); 
    } else {
      setFeedbackMessage("Incorrect. Demoting...");
      setTimeout(() => {
        handleProgression(false);
      }, 2000);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSubmitAnswer();
    }
  };

  // Progression Logic
  const handleProgression = (userCorrect: boolean) => {
    // Save current question info to persistent state before fetching new one
    if (question) {
        setLastTurnResult({
            isCorrect: userCorrect,
            correctAnswer: question.correctAnswer,
            explanation: question.explanation
        });
    }

    if (userCorrect) {
      switch (difficulty) {
        case Difficulty.EASY:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.HARD);
          fetchQuestion(Difficulty.HARD, genre);
          break;
        case Difficulty.HARD:
          setGameState(GameState.VICTORY);
          break;
      }
    } else {
      // Incorrect Answer Logic
      switch (difficulty) {
        case Difficulty.HARD:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.EASY);
          fetchQuestion(Difficulty.EASY, genre);
          break;
        case Difficulty.EASY:
          // Stay on Easy
          fetchQuestion(Difficulty.EASY, genre);
          break;
      }
    }
  };

  const startGame = (selectedGenre: string) => {
    // Initialize audio context on user gesture
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    setLastTurnResult(null);
    fetchQuestion(Difficulty.EASY, selectedGenre);
  };

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setLastTurnResult(null);
    setCustomGenreInput('');
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (!isMuted) {
      stopAudio();
    }
  };

  // Render Methods
  const renderWelcome = () => (
    <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 drop-shadow-lg">
          ASCENSION
        </h1>
        <p className="text-xl text-slate-300 font-light tracking-wide">
          Prove your worth. Ascend to victory.
        </p>
      </div>

      <div className="w-full glass-panel p-8 rounded-3xl shadow-2xl shadow-indigo-900/20">
        <h2 className="text-2xl font-semibold mb-6 text-white">Select Your Realm</h2>

        {/* Predefined Genres */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {GENRES.map((g) => (
            <button
              key={g}
              onClick={() => startGame(g)}
              className="group relative p-4 rounded-xl bg-slate-800/50 hover:bg-indigo-600/20 border border-slate-700 hover:border-indigo-400 transition-all duration-300 overflow-hidden"
            >
              <span className="relative z-10 font-medium text-slate-200 group-hover:text-white transition-colors">{g}</span>
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/0 to-purple-600/0 group-hover:from-indigo-600/10 group-hover:to-purple-600/20 transition-all duration-300"></div>
            </button>
          ))}
          <button
              onClick={() => startGame("General Knowledge")}
              className="col-span-2 md:col-span-4 mt-2 p-4 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold tracking-wider shadow-lg shadow-indigo-900/40 transition-all active:scale-95"
            >
              SURPRISE ME (RANDOM)
          </button>
        </div>

        {/* Custom Genre Input */}
        <div className="pt-8 border-t border-slate-700/50">
          <p className="text-slate-400 text-sm mb-4 uppercase tracking-widest font-semibold">Or forge your own path</p>
          <div className="flex flex-col md:flex-row gap-3">
            <input
              type="text"
              value={customGenreInput}
              onChange={(e) => setCustomGenreInput(e.target.value)}
              placeholder="E.g., 90s Hip Hop, Quantum Physics, Cheese..."
              className="flex-1 bg-slate-800/50 border border-slate-600 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && customGenreInput.trim()) {
                  startGame(customGenreInput);
                }
              }}
            />
            <button
              onClick={() => customGenreInput.trim() && startGame(customGenreInput)}
              disabled={!customGenreInput.trim()}
              className="px-6 py-3 rounded-xl bg-slate-700 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg active:scale-95 whitespace-nowrap"
            >
              Start Custom
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderGame = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">

      {/* Header */}
      <div className="w-full flex justify-between items-center mb-6 bg-slate-900/40 p-4 rounded-2xl border border-slate-800/50 backdrop-blur-md">
        <button onClick={restartGame} className="text-sm font-medium text-slate-500 hover:text-white transition-colors flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Abort
        </button>

        <div className="flex items-center space-x-4">
           {/* Audio Toggle */}
           <button 
             onClick={toggleMute} 
             className={`p-2 rounded-full transition-colors ${isMuted ? 'text-slate-600 hover:text-slate-400' : 'text-indigo-400 hover:text-indigo-300 bg-indigo-400/10'}`}
             title={isMuted ? "Unmute Host" : "Mute Host"}
           >
             {isMuted ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
                </svg>
             ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                </svg>
             )}
           </button>
           <DifficultyBadge difficulty={difficulty} />
        </div>
      </div>

      {/* Previous Answer Feedback (Visible during loading and next question) */}
      {lastTurnResult && (
        <div className={`w-full mb-6 p-4 rounded-xl border ${lastTurnResult.isCorrect ? "bg-emerald-950/30 border-emerald-800/50" : "bg-rose-950/30 border-rose-800/50"} animate-[fadeIn_0.5s_ease-out]`}>
           <div className="flex items-center gap-2 mb-2">
             <span className={`font-bold text-sm uppercase tracking-wider ${lastTurnResult.isCorrect ? "text-emerald-400" : "text-rose-400"}`}>
               {lastTurnResult.isCorrect ? "Previous: Correct" : "Previous: Incorrect"}
             </span>
             <span className="text-slate-600">|</span>
             <span className="text-slate-300 text-sm">Answer: <span className="font-semibold text-white">{lastTurnResult.correctAnswer}</span></span>
           </div>
           <p className="text-slate-300 text-sm leading-relaxed italic opacity-90">
              "{lastTurnResult.explanation}"
           </p>
        </div>
      )}

      {loading ? (
        <LoadingSpinner />
      ) : question ? (
        <div className="w-full space-y-8 animate-[fadeIn_0.5s_ease-out]">

          {/* Question Card */}
          <div className="glass-panel p-8 rounded-3xl shadow-2xl relative overflow-hidden">
             {/* Progress bar background hint */}
             <div className={`absolute top-0 left-0 h-1 w-full ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'} opacity-30`}></div>

             <div className="space-y-2 mb-2">
                <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">{genre}</span>
             </div>
             <h2 className="text-2xl md:text-3xl font-bold leading-tight text-white mb-6">
              {question.questionText}
            </h2>

            {/* Answer Input */}
            <div className="flex flex-col md:flex-row gap-3">
              <input
                ref={inputRef}
                type="text"
                value={userAnswer}
                onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isAnswerRevealed}
                placeholder="Type your answer..."
                autoComplete="off"
                className={`flex-1 bg-slate-900/50 border-2 rounded-xl px-5 py-4 text-xl text-white placeholder-slate-500 focus:outline-none transition-all ${
                  isAnswerRevealed
                    ? isCorrect
                      ? 'border-emerald-500 bg-emerald-900/20'
                      : 'border-rose-500 bg-rose-900/20'
                    : 'border-slate-600 focus:border-indigo-500 focus:shadow-[0_0_15px_rgba(99,102,241,0.3)]'
                }`}
              />
              <Button 
                onClick={handleSubmitAnswer}
                disabled={!userAnswer.trim() || isAnswerRevealed}
                className="whitespace-nowrap md:w-auto"
              >
                Submit
              </Button>
            </div>
          </div>

          {/* Current Feedback (Visible immediately after answering) */}
          {isAnswerRevealed && (
            <div className={`mt-6 p-6 rounded-2xl glass-panel border-l-4 ${isCorrect ? 'border-emerald-500' : 'border-rose-500'} animate-[slideUp_0.3s_ease-out]`}>
              <div className="flex items-center space-x-3 mb-2">
                 <span className={`font-bold ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isCorrect ? 'Correct!' : 'Incorrect'}
                 </span>
                 {!isCorrect && (
                   <span className="text-slate-300">
                     The answer was: <span className="font-bold text-white">{question.correctAnswer}</span>
                   </span>
                 )}
                 <span className="text-slate-500">|</span>
                 <span className="text-slate-400 text-sm">Next question loading...</span>
              </div>
              <p className="text-slate-200 leading-relaxed mt-3">
                {question.explanation}
              </p>
            </div>
          )}

        </div>
      ) : null}
    </div>
  );

  const renderVictory = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
      <div className="glass-panel p-10 md:p-16 rounded-[3rem] shadow-2xl shadow-indigo-500/20 max-w-2xl border-indigo-500/30 animate-[zoomIn_0.5s_ease-out]">
        <div className="mb-8 inline-block p-4 rounded-full bg-indigo-500/20 text-indigo-300 mb-6">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
           </svg>
        </div>
        <h1 className="text-5xl md:text-7xl font-black text-white mb-6 tracking-tight">
          VICTORY
        </h1>
        <p className="text-xl md:text-2xl text-slate-300 mb-10 leading-relaxed">
          You have conquered the <span className="text-indigo-400 font-bold">Hard</span> difficulty and proven your intellect in the realm of {genre}.
        </p>
        <Button onClick={restartGame} variant="primary" className="text-lg px-10 py-4 shadow-indigo-500/50 hover:shadow-indigo-500/80">
          Play Again
        </Button>
      </div>
    </div>
  );

  // Background Elements
  const Background = () => (
    <div className="fixed inset-0 z-0">
       <div className="absolute inset-0 bg-slate-950"></div>
       <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-indigo-950 via-slate-950 to-slate-950 opacity-80"></div>
       <div className="absolute top-[-20%] right-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/20 blur-[120px]"></div>
       <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px]"></div>
    </div>
  );

  return (
    <div className="relative w-full min-h-screen font-sans">
      <Background />
      {gameState === GameState.WELCOME && renderWelcome()}
      {gameState === GameState.PLAYING && renderGame()}
      {gameState === GameState.VICTORY && renderVictory()}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { Difficulty, TriviaQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questionText: {
      type: Type.STRING,
      description: "The trivia question text. It should be answerable with a short phrase or single word."
    },
    acceptedAnswers: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of valid answers. Include synonyms, abbreviations, and common variations. Crucial: Include versions with and without leading articles (e.g. ['The Treaty of Versailles', 'Treaty of Versailles']).",
    },
    correctAnswer: {
      type: Type.STRING,
      description: "The primary correct answer to display to the user.",
    },
    explanation: {
      type: Type.STRING,
      description: "A brief interesting fact explaining the answer.",
    }
  },
  required: ["questionText", "acceptedAnswers", "correctAnswer", "explanation"],
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateTriviaQuestion = async (
  genre: string, 
  difficulty: Difficulty, 
  previousQuestions: string[] = []
): Promise<TriviaQuestion> => {
  // Upgrading to gemini-3-flash-preview for better logic and variation handling
  const model = "gemini-3-flash-preview";

  const prompt = `
    Generate a ${difficulty.toLowerCase()} difficulty open-ended trivia question about "${genre}".

    Difficulty Guidelines:
    - Easy: Common knowledge, simple answers.
    - Medium: Requires specific knowledge.
    - Hard: Obscure facts, specific names/dates.

    Constraints:
    - The answer must be concise (1-4 words).
    - Provide at least 5-10 variations in 'acceptedAnswers' to be extremely forgiving to the user.
    - MANDATORY: Include variations with and without articles (a, an, the).
    - MANDATORY: Include common abbreviations and shorthand.
    - Do not mention the difficulty level in the question text.

    CRITICAL INSTRUCTIONS FOR VARIETY:
    1. Select a random sub-topic or specific niche within "${genre}".
    2. AVOID DUPLICATION: Do not generate questions similar to these:
       ${JSON.stringify(previousQuestions)}
  `;

  let lastError: any;

  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: questionSchema,
          temperature: 0.9, 
        },
      });

      const text = response.text;
      if (!text) {
          throw new Error("Empty response from Gemini");
      }

      const data = JSON.parse(text) as TriviaQuestion;
      return data;
    } catch (error: any) {
      console.error(`Attempt ${attempt} failed:`, error);
      lastError = error;
      if (attempt < 3) {
        await delay(1000 * Math.pow(2, attempt - 1));
      }
    }
  }

  return {
    questionText: `System Error: ${lastError?.message || "Unknown error"}. Please type 'retry' to continue.`,
    acceptedAnswers: ["retry"],
    correctAnswer: "retry",
    explanation: "Sometimes API calls fail. Please try again."
  };
};

export const generateTriviaAudio = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Fenrir' },
            },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio || null;
  } catch (error) {
    console.error("Audio generation failed:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES, DIFFICULTY_COLORS } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

interface LastTurnResult {
  isCorrect: boolean;
  correctAnswer: string;
  explanation: string;
}

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Custom Genre Input State
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  // Turn State
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isCorrect, setIsCorrect] = useState<boolean>(false);

  // Persistent Feedback State
  const [lastTurnResult, setLastTurnResult] = useState<LastTurnResult | null>(null);

  // History State (persisted in localStorage)
  const [history, setHistory] = useState<string[]>([]);

  // Audio State
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize Audio Context lazily
  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopCurrentSource = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Ignore errors if already stopped
      }
      currentSourceRef.current = null;
    }
  };

  const stopAudio = () => {
    // Invalidate any pending async tasks that might try to play audio later
    audioRequestIdRef.current += 1;
    stopCurrentSource();
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const pcm16 = new Int16Array(bytes.buffer);
      const sampleRate = 24000; // Gemini TTS default sample rate

      // Create buffer with the correct sample rate
      const buffer = ctx.createBuffer(1, pcm16.length, sampleRate);
      const channelData = buffer.getChannelData(0);

      for (let i = 0; i < pcm16.length; i++) {
          // Normalize 16-bit integer to float [-1.0, 1.0]
          channelData[i] = pcm16[i] / 32768.0;
      }

      return buffer;
  };

  const playAudio = async (base64Data: string) => {
    if (isMuted) return;

    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      stopCurrentSource();

      // Decode raw PCM data manually instead of using decodeAudioData which expects headers
      const buffer = decodePCM(base64Data, ctx);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
    }
  };

  const speak = useCallback(async (text: string) => {
    if (isMuted) return;

    // Increment ID to cancel any pending previous requests
    stopAudio();
    const myRequestId = audioRequestIdRef.current;

    const audioData = await generateTriviaAudio(text);

    // If the ID has changed since we started, it means stopAudio() or speak() 
    // was called again (e.g. user moved to next question). We should abandon this audio.
    if (audioRequestIdRef.current !== myRequestId) {
        return;
    }

    if (audioData) {
      playAudio(audioData);
    }
  }, [isMuted]);

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('trivia_history');
    if (saved) {
        try {
            setHistory(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to parse history", e);
        }
    }
  }, []);

  // Update history helper
  const addToHistory = (newQuestionText: string) => {
    setHistory(prev => {
        // Keep only the last 100 questions to maintain context window efficiency
        const newHistory = [newQuestionText, ...prev].slice(0, 100);
        localStorage.setItem('trivia_history', JSON.stringify(newHistory));
        return newHistory;
    });
  };

  // Auto-narrate question when it loads
  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      // Small delay to ensure smooth transition
      const timer = setTimeout(() => {
         speak(question.questionText);
         // Focus input on new question
         if (inputRef.current) {
            inputRef.current.focus();
         }
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading, speak]);

  // Auto-narrate result when answer revealed
  useEffect(() => {
    if (isAnswerRevealed && question) {
      const prefix = isCorrect ? "Correct!" : `Incorrect. The answer is ${question.correctAnswer}.`;
      const textToSpeak = `${prefix} ${question.explanation}`;
      speak(textToSpeak);
    }
  }, [isAnswerRevealed, isCorrect, question, speak]);

  // Fetch a new question based on current state
  const fetchQuestion = useCallback(async (targetDifficulty: Difficulty, targetGenre: string) => {
    setLoading(true);
    setQuestion(null);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setFeedbackMessage('');
    setIsCorrect(false);

    try {
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, history);
      setQuestion(newQuestion);

      if (newQuestion && newQuestion.questionText && !newQuestion.questionText.includes("error")) {
        addToHistory(newQuestion.questionText);
      }
    } catch (error) {
      console.error("Failed to fetch question", error);
    } finally {
      setLoading(false);
    }
  }, [history]); 

  // Normalize string for fuzzy matching
  const normalizeAnswer = (str: string) => {
    return str.toLowerCase()
      .replace(/[^\w\s]|_/g, "") // Remove punctuation
      .replace(/\s+/g, " ")      // Collapse spaces
      .trim()
      .replace(/^(the|a|an)\s+/i, ""); // Strip leading articles
  };

  const handleSubmitAnswer = () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    setLastTurnResult(null);
    stopAudio(); 
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = normalizeAnswer(userAnswer);
    const match = question.acceptedAnswers.some(ans => normalizeAnswer(ans) === normalizedUserAnswer);

    setIsCorrect(match);

    if (match) {
      setFeedbackMessage("Correct!");
      setTimeout(() => {
        handleProgression(true);
      }, 1500); 
    } else {
      setFeedbackMessage("Incorrect.");
      setTimeout(() => {
        handleProgression(false);
      }, 2000);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSubmitAnswer();
    }
  };

  // Progression Logic
  const handleProgression = (userCorrect: boolean) => {
    if (question) {
        setLastTurnResult({
            isCorrect: userCorrect,
            correctAnswer: question.correctAnswer,
            explanation: question.explanation
        });
    }

    if (userCorrect) {
      switch (difficulty) {
        case Difficulty.EASY:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.HARD);
          fetchQuestion(Difficulty.HARD, genre);
          break;
        case Difficulty.HARD:
          setGameState(GameState.VICTORY);
          break;
      }
    } else {
      switch (difficulty) {
        case Difficulty.HARD:
          setDifficulty(Difficulty.MEDIUM);
          fetchQuestion(Difficulty.MEDIUM, genre);
          break;
        case Difficulty.MEDIUM:
          setDifficulty(Difficulty.EASY);
          fetchQuestion(Difficulty.EASY, genre);
          break;
        case Difficulty.EASY:
          fetchQuestion(Difficulty.EASY, genre);
          break;
      }
    }
  };

  const startGame = (selectedGenre: string) => {
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    setLastTurnResult(null);
    fetchQuestion(Difficulty.EASY, selectedGenre);
  };

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setLastTurnResult(null);
    setCustomGenreInput('');
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (!isMuted) {
      stopAudio();
    }
  };

  const renderWelcome = () => (
    <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 drop-shadow-lg">
          ASCENSION
        </h1>
        <p className="text-xl text-slate-300 font-light tracking-wide">
          Prove your worth. Ascend to victory.
        </p>
      </div>

      <div className="w-full glass-panel p-8 rounded-3xl shadow-2xl shadow-indigo-900/20">
        <h2 className="text-2xl font-semibold mb-6 text-white">Select Your Realm</h2>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {GENRES.map((g) => (
            <button
              key={g}
              onClick={() => startGame(g)}
              className="group relative p-4 rounded-xl bg-slate-800/50 hover:bg-indigo-600/20 border border-slate-700 hover:border-indigo-400 transition-all duration-300 overflow-hidden"
            >
              <span className="relative z-10 font-medium text-slate-200 group-hover:text-white transition-colors">{g}</span>
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/0 to-purple-600/0 group-hover:from-indigo-600/10 group-hover:to-purple-600/20 transition-all duration-300"></div>
            </button>
          ))}
          <button
              onClick={() => startGame("General Knowledge")}
              className="col-span-2 md:col-span-4 mt-2 p-4 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold tracking-wider shadow-lg shadow-indigo-900/40 transition-all active:scale-95"
            >
              SURPRISE ME (RANDOM)
          </button>
        </div>

        <div className="pt-8 border-t border-slate-700/50">
          <p className="text-slate-400 text-sm mb-4 uppercase tracking-widest font-semibold">Or forge your own path</p>
          <div className="flex flex-col md:flex-row gap-3">
            <input
              type="text"
              value={customGenreInput}
              onChange={(e) => setCustomGenreInput(e.target.value)}
              placeholder="E.g., 90s Hip Hop, Quantum Physics, Cheese..."
              className="flex-1 bg-slate-800/50 border border-slate-600 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && customGenreInput.trim()) {
                  startGame(customGenreInput);
                }
              }}
            />
            <button
              onClick={() => customGenreInput.trim() && startGame(customGenreInput)}
              disabled={!customGenreInput.trim()}
              className="px-6 py-3 rounded-xl bg-slate-700 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg active:scale-95 whitespace-nowrap"
            >
              Start Custom
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderGame = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">

      <div className="w-full flex justify-between items-center mb-6 bg-slate-900/40 p-4 rounded-2xl border border-slate-800/50 backdrop-blur-md">
        <button onClick={restartGame} className="text-sm font-medium text-slate-500 hover:text-white transition-colors flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Abort
        </button>

        <div className="flex items-center space-x-4">
           <button 
             onClick={toggleMute} 
             className={`p-2 rounded-full transition-colors ${isMuted ? 'text-slate-600 hover:text-slate-400' : 'text-indigo-400 hover:text-indigo-300 bg-indigo-400/10'}`}
             title={isMuted ? "Unmute Host" : "Mute Host"}
           >
             {isMuted ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
                </svg>
             ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                </svg>
             )}
           </button>
           <DifficultyBadge difficulty={difficulty} />
        </div>
      </div>

      {lastTurnResult && (
        <div className={`w-full mb-6 p-4 rounded-xl border ${lastTurnResult.isCorrect ? "bg-emerald-950/30 border-emerald-800/50" : "bg-rose-950/30 border-rose-800/50"} animate-[fadeIn_0.5s_ease-out]`}>
           <div className="flex items-center gap-2 mb-2">
             <span className={`font-bold text-sm uppercase tracking-wider ${lastTurnResult.isCorrect ? "text-emerald-400" : "text-rose-400"}`}>
               {lastTurnResult.isCorrect ? "Previous: Correct" : "Previous: Incorrect"}
             </span>
             <span className="text-slate-600">|</span>
             <span className="text-slate-300 text-sm">Answer: <span className="font-semibold text-white">{lastTurnResult.correctAnswer}</span></span>
           </div>
           <p className="text-slate-300 text-sm leading-relaxed italic opacity-90">
              "{lastTurnResult.explanation}"
           </p>
        </div>
      )}

      {loading ? (
        <LoadingSpinner />
      ) : question ? (
        <div className="w-full space-y-8 animate-[fadeIn_0.5s_ease-out]">

          <div className="glass-panel p-8 rounded-3xl shadow-2xl relative overflow-hidden">
             <div className={`absolute top-0 left-0 h-1 w-full ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'} opacity-30`}></div>

             <div className="space-y-2 mb-2">
                <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">{genre}</span>
             </div>
             <h2 className="text-2xl md:text-3xl font-bold leading-tight text-white mb-6">
              {question.questionText}
            </h2>

            <div className="flex flex-col md:flex-row gap-3">
              <input
                ref={inputRef}
                type="text"
                value={userAnswer}
                onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isAnswerRevealed}
                placeholder="Type your answer..."
                autoComplete="off"
                className={`flex-1 bg-slate-900/50 border-2 rounded-xl px-5 py-4 text-xl text-white placeholder-slate-500 focus:outline-none transition-all ${
                  isAnswerRevealed
                    ? isCorrect
                      ? 'border-emerald-500 bg-emerald-900/20'
                      : 'border-rose-500 bg-rose-900/20'
                    : 'border-slate-600 focus:border-indigo-500 focus:shadow-[0_0_15px_rgba(99,102,241,0.3)]'
                }`}
              />
              <Button 
                onClick={handleSubmitAnswer}
                disabled={!userAnswer.trim() || isAnswerRevealed}
                className="whitespace-nowrap md:w-auto"
              >
                Submit
              </Button>
            </div>
          </div>

          {isAnswerRevealed && (
            <div className={`mt-6 p-6 rounded-2xl glass-panel border-l-4 ${isCorrect ? 'border-emerald-500' : 'border-rose-500'} animate-[slideUp_0.3s_ease-out]`}>
              <div className="flex items-center space-x-3 mb-2">
                 <span className={`font-bold ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isCorrect ? 'Correct!' : 'Incorrect'}
                 </span>
                 {!isCorrect && (
                   <span className="text-slate-300">
                     The answer was: <span className="font-bold text-white">{question.correctAnswer}</span>
                   </span>
                 )}
                 <span className="text-slate-500">|</span>
                 <span className="text-slate-400 text-sm">Next question loading...</span>
              </div>
              <p className="text-slate-200 leading-relaxed mt-3">
                {question.explanation}
              </p>
            </div>
          )}

        </div>
      ) : null}
    </div>
  );

  const renderVictory = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
      <div className="glass-panel p-10 md:p-16 rounded-[3rem] shadow-2xl shadow-indigo-500/20 max-w-2xl border-indigo-500/30 animate-[zoomIn_0.5s_ease-out]">
        <div className="mb-8 inline-block p-4 rounded-full bg-indigo-500/20 text-indigo-300 mb-6">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
           </svg>
        </div>
        <h1 className="text-5xl md:text-7xl font-black text-white mb-6 tracking-tight">
          VICTORY
        </h1>
        <p className="text-xl md:text-2xl text-slate-300 mb-10 leading-relaxed">
          You have conquered the <span className="text-indigo-400 font-bold">Hard</span> difficulty and proven your intellect in the realm of {genre}.
        </p>
        <Button onClick={restartGame} variant="primary" className="text-lg px-10 py-4 shadow-indigo-500/50 hover:shadow-indigo-500/80">
          Play Again
        </Button>
      </div>
    </div>
  );

  const Background = () => (
    <div className="fixed inset-0 z-0">
       <div className="absolute inset-0 bg-slate-950"></div>
       <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-indigo-950 via-slate-950 to-slate-950 opacity-80"></div>
       <div className="absolute top-[-20%] right-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/20 blur-[120px]"></div>
       <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px]"></div>
    </div>
  );

  return (
    <div className="relative w-full min-h-screen font-sans">
      <Background />
      {gameState === GameState.WELCOME && renderWelcome()}
      {gameState === GameState.PLAYING && renderGame()}
      {gameState === GameState.VICTORY && renderVictory()}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { Difficulty, TriviaQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questionText: {
      type: Type.STRING,
      description: "The trivia question text sourced from a Wikipedia-style fact."
    },
    acceptedAnswers: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of valid answers including variations with/without articles and abbreviations.",
    },
    correctAnswer: {
      type: Type.STRING,
      description: "The primary correct answer.",
    },
    explanation: {
      type: Type.STRING,
      description: "An interesting fact explaining the answer, derived from Wikipedia content.",
    }
  },
  required: ["questionText", "acceptedAnswers", "correctAnswer", "explanation"],
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateTriviaQuestion = async (
  genre: string, 
  difficulty: Difficulty, 
  previousQuestions: string[] = []
): Promise<TriviaQuestion> => {
  const model = "gemini-3-flash-preview";

  const prompt = `
    Use Google Search to find Wikipedia articles related to "${genre}". 
    From those articles, find an interesting, verifiable fact to create a ${difficulty.toLowerCase()} difficulty trivia question.

    RESEARCH TARGET: Focus on a specific sub-topic or person within "${genre}" to ensure high variety.

    Difficulty Guidelines:
    - Easy: General, well-known facts found in the intro of popular articles.
    - Medium: Facts from middle sections of articles, requiring some depth.
    - Hard: Obscure details, niche figures, or specific dates/names from deep within Wikipedia.

    Constraints:
    - The answer must be 1-4 words.
    - Provide 5-10 variations in 'acceptedAnswers'. Include versions with and without articles (a, an, the).
    - AVOID REPETITION: Do not use facts similar to these: ${JSON.stringify(previousQuestions.slice(0, 10))}.
    - Ensure the question is sourced from real-world data found via search.
  `;

  let lastError: any;

  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: questionSchema,
          temperature: 1.0, 
          tools: [{ googleSearch: {} }]
        },
      });

      const text = response.text;
      if (!text) throw new Error("Empty response from Gemini");

      return JSON.parse(text) as TriviaQuestion;
    } catch (error: any) {
      console.error(`Attempt ${attempt} failed:`, error);
      lastError = error;
      if (attempt < 3) await delay(1500 * attempt);
    }
  }

  return {
    questionText: `System Error: ${lastError?.message || "Connectivity issue"}. Type 'retry' to continue.`,
    acceptedAnswers: ["retry"],
    correctAnswer: "retry",
    explanation: "I encountered a technical hurdle while researching. Let's try once more."
  };
};

export const generateTriviaAudio = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Fenrir' },
            },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (error) {
    console.error("Audio generation failed:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

interface LastTurnResult {
  isCorrect: boolean;
  correctAnswer: string;
  explanation: string;
}

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // UI State
  const [customGenreInput, setCustomGenreInput] = useState<string>('');
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [isCorrect, setIsCorrect] = useState<boolean>(false);
  const [lastTurnResult, setLastTurnResult] = useState<LastTurnResult | null>(null);
  const [history, setHistory] = useState<string[]>([]);

  // Audio State
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopAudio = () => {
    audioRequestIdRef.current += 1;
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.onended = null;
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
      const binaryString = atob(base64Data);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
      const pcm16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, pcm16.length, 24000);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < pcm16.length; i++) channelData[i] = pcm16[i] / 32768.0;
      return buffer;
  };

  const playAudio = (base64Data: string, onEnded?: () => void): void => {
    if (isMuted) {
      onEnded?.();
      return;
    }
    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') ctx.resume();
      stopAudio();
      const buffer = decodePCM(base64Data, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        currentSourceRef.current = null;
        onEnded?.();
      };
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
      onEnded?.();
    }
  };

  const speak = useCallback(async (text: string, onEnded?: () => void) => {
    if (isMuted) {
      onEnded?.();
      return;
    }
    const myRequestId = ++audioRequestIdRef.current;
    const audioData = await generateTriviaAudio(text);
    if (audioRequestIdRef.current === myRequestId && audioData) {
      playAudio(audioData, onEnded);
    } else {
      onEnded?.();
    }
  }, [isMuted]);

  useEffect(() => {
    const saved = localStorage.getItem('trivia_history');
    if (saved) try { setHistory(JSON.parse(saved)); } catch (e) {}
  }, []);

  const addToHistory = (newQuestionText: string) => {
    setHistory(prev => {
        const newHistory = [newQuestionText, ...prev].slice(0, 100);
        localStorage.setItem('trivia_history', JSON.stringify(newHistory));
        return newHistory;
    });
  };

  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      const timer = setTimeout(() => {
         speak(question.questionText);
         if (inputRef.current) inputRef.current.focus();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading, speak]);

  const fetchQuestion = useCallback(async (targetDifficulty: Difficulty, targetGenre: string) => {
    setLoading(true);
    setQuestion(null);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setIsCorrect(false);

    try {
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, history);
      setQuestion(newQuestion);
      if (newQuestion && newQuestion.questionText && !newQuestion.questionText.includes("error")) {
        addToHistory(newQuestion.questionText);
      }
    } catch (error) {
      console.error("Failed to fetch question", error);
    } finally {
      setLoading(false);
    }
  }, [history]); 

  const normalizeAnswer = (str: string) => {
    return str.toLowerCase()
      .replace(/[^\w\s]|_/g, "")
      .replace(/\s+/g, " ")
      .trim()
      .replace(/^(the|a|an)\s+/i, "");
  };

  const handleProgression = (userCorrect: boolean) => {
    if (question) {
        setLastTurnResult({
            isCorrect: userCorrect,
            correctAnswer: question.correctAnswer,
            explanation: question.explanation
        });
    }

    let nextDifficulty = difficulty;
    if (userCorrect) {
      if (difficulty === Difficulty.EASY) nextDifficulty = Difficulty.MEDIUM;
      else if (difficulty === Difficulty.MEDIUM) nextDifficulty = Difficulty.HARD;
      else { setGameState(GameState.VICTORY); return; }
    } else {
      if (difficulty === Difficulty.HARD) nextDifficulty = Difficulty.MEDIUM;
      else if (difficulty === Difficulty.MEDIUM) nextDifficulty = Difficulty.EASY;
    }

    setDifficulty(nextDifficulty);
    fetchQuestion(nextDifficulty, genre);
  };

  const handleSubmitAnswer = () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    setLastTurnResult(null);
    stopAudio(); 
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = normalizeAnswer(userAnswer);
    const match = question.acceptedAnswers.some(ans => normalizeAnswer(ans) === normalizedUserAnswer);
    setIsCorrect(match);

    const prefix = match ? "Correct!" : `Incorrect. The answer is ${question.correctAnswer}.`;
    const fullText = `${prefix} ${question.explanation}`;

    // Wait for the TTS to finish before moving to the next question
    speak(fullText, () => {
      // Small buffer after audio ends to let user digest
      setTimeout(() => {
        handleProgression(match);
      }, 800);
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSubmitAnswer();
  };

  const startGame = (selectedGenre: string) => {
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    setLastTurnResult(null);
    fetchQuestion(Difficulty.EASY, selectedGenre);
  };

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setLastTurnResult(null);
    setCustomGenreInput('');
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (!isMuted) stopAudio();
  };

  const renderWelcome = () => (
    <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
      <div className="mb-12 space-y-4">
        <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 drop-shadow-lg">
          ASCENSION
        </h1>
        <p className="text-xl text-slate-300 font-light tracking-wide">
          Wikipedia-sourced trivia. Prove your intellect.
        </p>
      </div>

      <div className="w-full glass-panel p-8 rounded-3xl shadow-2xl shadow-indigo-900/20">
        <h2 className="text-2xl font-semibold mb-6 text-white">Select Your Realm</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {GENRES.map((g) => (
            <button key={g} onClick={() => startGame(g)} className="group relative p-4 rounded-xl bg-slate-800/50 hover:bg-indigo-600/20 border border-slate-700 hover:border-indigo-400 transition-all duration-300 overflow-hidden">
              <span className="relative z-10 font-medium text-slate-200 group-hover:text-white transition-colors">{g}</span>
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/0 to-purple-600/0 group-hover:from-indigo-600/10 group-hover:to-purple-600/20 transition-all duration-300"></div>
            </button>
          ))}
          <button onClick={() => startGame("General Knowledge")} className="col-span-2 md:col-span-4 mt-2 p-4 rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold tracking-wider shadow-lg shadow-indigo-900/40 transition-all active:scale-95">
            RANDOM RESEARCH
          </button>
        </div>

        <div className="pt-8 border-t border-slate-700/50">
          <p className="text-slate-400 text-sm mb-4 uppercase tracking-widest font-semibold">Custom Research Topic</p>
          <div className="flex flex-col md:flex-row gap-3">
            <input type="text" value={customGenreInput} onChange={(e) => setCustomGenreInput(e.target.value)} placeholder="Topic..." className="flex-1 bg-slate-800/50 border border-slate-600 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:border-indigo-500 focus:outline-none transition-all" onKeyDown={(e) => e.key === 'Enter' && customGenreInput.trim() && startGame(customGenreInput)} />
            <button onClick={() => customGenreInput.trim() && startGame(customGenreInput)} disabled={!customGenreInput.trim()} className="px-6 py-3 rounded-xl bg-slate-700 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50 transition-all active:scale-95">Start</button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderGame = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">
      <div className="w-full flex justify-between items-center mb-6 bg-slate-900/40 p-4 rounded-2xl border border-slate-800/50 backdrop-blur-md">
        <button onClick={restartGame} className="text-sm font-medium text-slate-500 hover:text-white transition-colors flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          Abort
        </button>
        <div className="flex items-center space-x-4">
           <button onClick={toggleMute} className={`p-2 rounded-full transition-colors ${isMuted ? 'text-slate-600' : 'text-indigo-400 bg-indigo-400/10'}`}>
             {isMuted ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" /></svg>
             ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
             )}
           </button>
           <DifficultyBadge difficulty={difficulty} />
        </div>
      </div>

      {lastTurnResult && (
        <div className={`w-full mb-6 p-4 rounded-xl border ${lastTurnResult.isCorrect ? "bg-emerald-950/30 border-emerald-800/50" : "bg-rose-950/30 border-rose-800/50"} animate-[fadeIn_0.5s_ease-out]`}>
           <div className="flex items-center gap-2 mb-2">
             <span className={`font-bold text-sm uppercase tracking-wider ${lastTurnResult.isCorrect ? "text-emerald-400" : "text-rose-400"}`}>
               {lastTurnResult.isCorrect ? "Correct" : "Incorrect"}
             </span>
             <span className="text-slate-600">|</span>
             <span className="text-slate-300 text-sm">Answer: <span className="font-semibold text-white">{lastTurnResult.correctAnswer}</span></span>
           </div>
           <p className="text-slate-300 text-sm leading-relaxed italic opacity-90">"{lastTurnResult.explanation}"</p>
        </div>
      )}

      {loading ? (
        <LoadingSpinner />
      ) : question ? (
        <div className="w-full space-y-8 animate-[fadeIn_0.5s_ease-out]">
          <div className="glass-panel p-8 rounded-3xl shadow-2xl relative overflow-hidden">
             <div className={`absolute top-0 left-0 h-1 w-full ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'} opacity-30`}></div>
             <div className="mb-2"><span className="text-xs font-bold tracking-widest text-slate-400 uppercase">{genre}</span></div>
             <h2 className="text-2xl md:text-3xl font-bold text-white mb-6">{question.questionText}</h2>
            <div className="flex flex-col md:flex-row gap-3">
              <input ref={inputRef} type="text" value={userAnswer} onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)} onKeyDown={handleKeyDown} disabled={isAnswerRevealed} placeholder="Type your answer..." autoComplete="off" className={`flex-1 bg-slate-900/50 border-2 rounded-xl px-5 py-4 text-xl text-white focus:outline-none transition-all ${isAnswerRevealed ? (isCorrect ? 'border-emerald-500' : 'border-rose-500') : 'border-slate-600 focus:border-indigo-500'}`} />
              <Button onClick={handleSubmitAnswer} disabled={!userAnswer.trim() || isAnswerRevealed}>Submit</Button>
            </div>
          </div>
          {isAnswerRevealed && (
            <div className={`mt-6 p-6 rounded-2xl glass-panel border-l-4 ${isCorrect ? 'border-emerald-500' : 'border-rose-500'} animate-[slideUp_0.3s_ease-out]`}>
              <div className="flex items-center space-x-3 mb-2">
                 <span className={`font-bold ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>{isCorrect ? 'Correct!' : 'Incorrect'}</span>
                 {!isCorrect && <span className="text-slate-300">Answer: <span className="font-bold text-white">{question.correctAnswer}</span></span>}
              </div>
              <p className="text-slate-200 leading-relaxed mt-3">{question.explanation}</p>
              <div className="mt-4 text-xs text-indigo-400 font-semibold animate-pulse">Waiting for host to finish speaking...</div>
            </div>
          )}
        </div>
      ) : null}
    </div>
  );

  return (
    <div className="relative w-full min-h-screen font-sans">
      <div className="fixed inset-0 z-0 bg-slate-950">
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-950 via-slate-950 to-slate-950 opacity-80"></div>
        <div className="absolute top-[-20%] right-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/20 blur-[120px]"></div>
        <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px]"></div>
      </div>
      {gameState === GameState.WELCOME && renderWelcome()}
      {gameState === GameState.PLAYING && renderGame()}
      {gameState === GameState.VICTORY && (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
          <div className="glass-panel p-10 rounded-[3rem] shadow-2xl max-w-2xl border-indigo-500/30">
            <h1 className="text-6xl font-black text-white mb-6">VICTORY</h1>
            <p className="text-xl text-slate-300 mb-10">Conquered the realm of {genre}.</p>
            <Button onClick={restartGame}>Play Again</Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

interface LastTurnResult {
  isCorrect: boolean;
  correctAnswer: string;
  explanation: string;
}

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Current Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [isCorrect, setIsCorrect] = useState<boolean>(false);

  // Pipeline State (Pre-fetching)
  const [prefetchedAnswerAudio, setPrefetchedAnswerAudio] = useState<string | null>(null);
  const [prefetchedNextQuestion, setPrefetchedNextQuestion] = useState<TriviaQuestion | null>(null);
  const [isPrefetchingQuestion, setIsPrefetchingQuestion] = useState<boolean>(false);

  // History and Results
  const [lastTurnResult, setLastTurnResult] = useState<LastTurnResult | null>(null);
  const [history, setHistory] = useState<string[]>([]);
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Audio / Refs
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopAudio = () => {
    audioRequestIdRef.current += 1;
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.onended = null;
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const pcm16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, pcm16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < pcm16.length; i++) channelData[i] = pcm16[i] / 32768.0;
    return buffer;
  };

  const playAudio = (base64Data: string, onEnded?: () => void): void => {
    if (isMuted) {
      onEnded?.();
      return;
    }
    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') ctx.resume();
      stopAudio();
      const buffer = decodePCM(base64Data, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        currentSourceRef.current = null;
        onEnded?.();
      };
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
      onEnded?.();
    }
  };

  // Generate a question (either for immediate use or pre-fetch)
  const fetchQuestionData = async (targetDifficulty: Difficulty, targetGenre: string, hist: string[]) => {
    try {
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, hist);
      return newQuestion;
    } catch (error) {
      console.error("Failed to fetch question", error);
      return null;
    }
  };

  // Pre-fetch the TTS for the correct answer while the user is answering
  const prefetchAnswerAudio = useCallback(async (correctAnswer: string, explanation: string) => {
    if (isMuted) return;
    const text = `${correctAnswer}. ${explanation}`;
    const audioData = await generateTriviaAudio(text);
    if (audioData) setPrefetchedAnswerAudio(audioData);
  }, [isMuted]);

  // Handle actual transition to a new question
  const applyQuestion = useCallback((q: TriviaQuestion) => {
    setQuestion(q);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setIsCorrect(false);
    setPrefetchedAnswerAudio(null);
    setLoading(false);

    if (q && q.questionText && !q.questionText.includes("Error")) {
      // Add to history
      setHistory(prev => {
        const newHist = [q.questionText, ...prev].slice(0, 50);
        localStorage.setItem('trivia_history', JSON.stringify(newHist));
        return newHist;
      });

      // Start pre-fetching the answer TTS immediately
      prefetchAnswerAudio(q.correctAnswer, q.explanation);
    }
  }, [prefetchAnswerAudio]);

  // Initial load
  const startGame = async (selectedGenre: string) => {
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    setLoading(true);
    setQuestion(null);
    setPrefetchedNextQuestion(null);

    const q = await fetchQuestionData(Difficulty.EASY, selectedGenre, history);
    if (q) applyQuestion(q);
    else setLoading(false);
  };

  // Logic to move difficulty up/down
  const getNextDifficulty = (current: Difficulty, correct: boolean): Difficulty | 'VICTORY' => {
    if (correct) {
      if (current === Difficulty.EASY) return Difficulty.MEDIUM;
      if (current === Difficulty.MEDIUM) return Difficulty.HARD;
      return 'VICTORY';
    } else {
      if (current === Difficulty.HARD) return Difficulty.MEDIUM;
      return Difficulty.EASY;
    }
  };

  // Pre-fetch the next question based on probability or current state
  // Since we don't know if the user is right yet, we can't be 100% sure of difficulty
  // but we can pre-fetch as soon as they submit
  const triggerNextQuestionPrefetch = async (nextDiff: Difficulty | 'VICTORY', currentGenre: string) => {
    if (nextDiff === 'VICTORY') return;
    setIsPrefetchingQuestion(true);
    const q = await fetchQuestionData(nextDiff, currentGenre, history);
    setPrefetchedNextQuestion(q);
    setIsPrefetchingQuestion(false);
  };

  const handleSubmitAnswer = async () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    setLastTurnResult(null);
    stopAudio(); 
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = userAnswer.toLowerCase().trim().replace(/^(the|a|an)\s+/i, "").replace(/[^\w\s]/gi, "");
    const match = question.acceptedAnswers.some(ans => {
      const norm = ans.toLowerCase().trim().replace(/^(the|a|an)\s+/i, "").replace(/[^\w\s]/gi, "");
      return norm === normalizedUserAnswer;
    });

    setIsCorrect(match);

    // 1. Determine next difficulty
    const nextDiff = getNextDifficulty(difficulty, match);

    // 2. Start pre-fetching the next question data immediately in background
    if (nextDiff !== 'VICTORY') {
      triggerNextQuestionPrefetch(nextDiff, genre);
    }

    // 3. Play the trivia audio (Answer + Explanation)
    // We use the pre-fetched audio if available, otherwise generate on the fly
    const playAndProceed = (audio: string) => {
      playAudio(audio, () => {
        setTimeout(() => {
          // Record this turn in the persistent display
          setLastTurnResult({
            isCorrect: match,
            correctAnswer: question.correctAnswer,
            explanation: question.explanation
          });

          if (nextDiff === 'VICTORY') {
            setGameState(GameState.VICTORY);
          } else {
            setDifficulty(nextDiff);
            // If the next question is ready, apply it. If not, wait for it.
            checkAndApplyNextQuestion();
          }
        }, 800);
      });
    };

    if (prefetchedAnswerAudio) {
      playAndProceed(prefetchedAnswerAudio);
    } else {
      const text = `${question.correctAnswer}. ${question.explanation}`;
      const freshAudio = await generateTriviaAudio(text);
      if (freshAudio) playAndProceed(freshAudio);
      else playAndProceed(""); // Fallback if audio fails
    }
  };

  // Helper to wait for background fetch if it's still running
  const checkAndApplyNextQuestion = useCallback(() => {
    if (prefetchedNextQuestion) {
      applyQuestion(prefetchedNextQuestion);
      setPrefetchedNextQuestion(null);
    } else {
      // If still prefetching, show loading briefly
      setLoading(true);
    }
  }, [prefetchedNextQuestion, applyQuestion]);

  // Effect to catch pre-fetched question if we were waiting for it
  useEffect(() => {
    if (loading && prefetchedNextQuestion && !isAnswerRevealed) {
      applyQuestion(prefetchedNextQuestion);
      setPrefetchedNextQuestion(null);
    }
  }, [loading, prefetchedNextQuestion, isAnswerRevealed, applyQuestion]);

  // Auto-speak question
  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      const timer = setTimeout(() => {
        const requestId = ++audioRequestIdRef.current;
        generateTriviaAudio(question.questionText).then(audio => {
          if (requestId === audioRequestIdRef.current && audio) {
            playAudio(audio);
          }
        });
        if (inputRef.current) inputRef.current.focus();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading]);

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setPrefetchedNextQuestion(null);
    setLastTurnResult(null);
  };

  return (
    <div className="relative w-full min-h-screen font-sans bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      {/* Background */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-950/40 via-slate-950 to-slate-950"></div>
        <div className="absolute top-[-10%] right-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/10 blur-[120px]"></div>
      </div>

      {gameState === GameState.WELCOME && (
        <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
          <div className="mb-12 space-y-4 animate-[fadeIn_0.8s_ease-out]">
            <h1 className="text-7xl md:text-9xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-slate-500 drop-shadow-2xl">
              ASCENSION
            </h1>
            <p className="text-xl text-slate-400 font-medium tracking-widest uppercase opacity-80">
              Wikipedia Research Engine • Trivia Mode
            </p>
          </div>

          <div className="w-full glass-panel p-10 rounded-[2.5rem] shadow-2xl border-white/5 animate-[slideUp_0.6s_ease-out]">
            <h2 className="text-2xl font-bold mb-8 text-white/90">Choose Your Realm of Inquiry</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
              {GENRES.map((g) => (
                <button key={g} onClick={() => startGame(g)} className="group relative p-5 rounded-2xl bg-white/5 hover:bg-white/10 border border-white/5 hover:border-indigo-500/50 transition-all duration-300">
                  <span className="relative z-10 font-semibold text-slate-300 group-hover:text-white">{g}</span>
                </button>
              ))}
              <button onClick={() => startGame("General Knowledge")} className="col-span-2 md:col-span-4 mt-2 p-5 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold tracking-widest shadow-xl transition-all active:scale-95">
                RANDOM RESEARCH
              </button>
            </div>

            <div className="pt-8 border-t border-white/5">
              <div className="flex flex-col md:flex-row gap-3">
                <input type="text" value={customGenreInput} onChange={(e) => setCustomGenreInput(e.target.value)} placeholder="Specific Topic (e.g. Renaissance Art, 90s Games)" className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 transition-all" onKeyDown={(e) => e.key === 'Enter' && customGenreInput.trim() && startGame(customGenreInput)} />
                <Button onClick={() => startGame(customGenreInput)} disabled={!customGenreInput.trim()} className="px-10 rounded-2xl">Start</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.PLAYING && (
        <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">
          <div className="w-full flex justify-between items-center mb-6 bg-white/5 backdrop-blur-xl p-4 rounded-3xl border border-white/10">
            <button onClick={restartGame} className="text-sm font-bold text-slate-500 hover:text-white transition-colors flex items-center gap-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
              ABORT
            </button>
            <div className="flex items-center gap-4">
              <button onClick={() => setIsMuted(!isMuted)} className={`p-2.5 rounded-full ${isMuted ? 'text-slate-600' : 'text-indigo-400 bg-indigo-400/10'}`}>
                {isMuted ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" /></svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                )}
              </button>
              <DifficultyBadge difficulty={difficulty} />
            </div>
          </div>

          {lastTurnResult && (
            <div className={`w-full mb-6 p-6 rounded-3xl border animate-[fadeIn_0.5s_ease-out] backdrop-blur-md ${lastTurnResult.isCorrect ? "bg-emerald-500/5 border-emerald-500/20" : "bg-rose-500/5 border-rose-500/20"}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`w-2 h-2 rounded-full ${lastTurnResult.isCorrect ? "bg-emerald-400" : "bg-rose-400"}`}></div>
                <span className={`font-bold text-xs uppercase tracking-[0.2em] ${lastTurnResult.isCorrect ? "text-emerald-400" : "text-rose-400"}`}>
                  {lastTurnResult.isCorrect ? "Validated" : "Incorrect"}
                </span>
                <span className="text-white/20">|</span>
                <span className="text-slate-300 text-sm font-medium">ANSWER: <span className="text-white font-bold">{lastTurnResult.correctAnswer}</span></span>
              </div>
              <p className="text-slate-400 text-sm leading-relaxed italic">"{lastTurnResult.explanation}"</p>
            </div>
          )}

          {loading ? (
            <div className="flex flex-col items-center py-20">
              <LoadingSpinner />
              <p className="mt-4 text-xs font-bold tracking-[0.3em] text-indigo-500/60 uppercase animate-pulse">Researching Next Subject</p>
            </div>
          ) : question ? (
            <div className="w-full space-y-6 animate-[fadeIn_0.4s_ease-out]">
              <div className="glass-panel p-10 rounded-[3rem] shadow-2xl relative overflow-hidden border-white/5">
                <div className="absolute top-0 left-0 h-1.5 w-full bg-white/5">
                  <div className={`h-full transition-all duration-1000 ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'}`} style={{ width: difficulty === Difficulty.HARD ? '100%' : difficulty === Difficulty.MEDIUM ? '66%' : '33%' }}></div>
                </div>
                <div className="mb-4"><span className="text-xs font-black tracking-[0.3em] text-indigo-400/80 uppercase">{genre}</span></div>
                <h2 className="text-2xl md:text-4xl font-bold text-white leading-[1.2] mb-10">{question.questionText}</h2>
                <div className="flex flex-col md:flex-row gap-4">
                  <input ref={inputRef} type="text" value={userAnswer} onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSubmitAnswer()} disabled={isAnswerRevealed} placeholder="Type answer..." className={`flex-1 bg-white/5 border-2 rounded-2xl px-6 py-5 text-xl text-white focus:outline-none transition-all ${isAnswerRevealed ? (isCorrect ? 'border-emerald-500/50 bg-emerald-500/5' : 'border-rose-500/50 bg-rose-500/5') : 'border-white/10 focus:border-indigo-500'}`} />
                  <Button onClick={handleSubmitAnswer} disabled={!userAnswer.trim() || isAnswerRevealed} className="px-10 text-lg">SUBMIT</Button>
                </div>
              </div>

              {isAnswerRevealed && (
                <div className={`p-8 rounded-[2.5rem] glass-panel border-l-4 transition-all duration-500 ${isCorrect ? 'border-emerald-500 shadow-[0_0_30px_rgba(16,185,129,0.1)]' : 'border-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.1)]'}`}>
                  <div className="flex items-center gap-4 mb-4">
                    <span className={`text-sm font-black tracking-widest uppercase ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>{isCorrect ? 'Verified' : 'Incorrect'}</span>
                    {!isCorrect && <span className="text-slate-300 font-medium">Correct: <span className="text-white font-bold">{question.correctAnswer}</span></span>}
                  </div>
                  <p className="text-lg text-slate-200 leading-relaxed font-medium">{question.explanation}</p>
                  <div className="mt-8 flex items-center gap-3">
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    </div>
                    <span className="text-[10px] font-black tracking-[0.3em] text-indigo-500/60 uppercase">System Syncing Next Subject</span>
                  </div>
                </div>
              )}
            </div>
          ) : null}
        </div>
      )}

      {gameState === GameState.VICTORY && (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
          <div className="glass-panel p-16 rounded-[4rem] shadow-2xl max-w-2xl border-white/5 animate-[zoomIn_0.5s_ease-out]">
            <div className="mb-6 inline-block p-4 rounded-full bg-emerald-500/20 text-emerald-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 13l4 4L19 7" /></svg>
            </div>
            <h1 className="text-7xl font-black text-white mb-4">ASCENDED</h1>
            <p className="text-xl text-slate-400 mb-12">You have mastered the domain of {genre}.</p>
            <Button onClick={restartGame} className="px-12 py-5 text-xl rounded-2xl shadow-indigo-500/40">BEGIN NEW ASCENSION</Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, GameState, TriviaQuestion } from './types';
import { GENRES } from './constants';
import { generateTriviaQuestion, generateTriviaAudio } from './services/geminiService';
import { Button } from './components/Button';
import { LoadingSpinner } from './components/LoadingSpinner';
import { DifficultyBadge } from './components/DifficultyBadge';

interface LastTurnResult {
  isCorrect: boolean;
  correctAnswer: string;
  explanation: string;
}

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState>(GameState.WELCOME);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [genre, setGenre] = useState<string>('');

  // Current Question State
  const [question, setQuestion] = useState<TriviaQuestion | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [isAnswerRevealed, setIsAnswerRevealed] = useState<boolean>(false);
  const [isCorrect, setIsCorrect] = useState<boolean>(false);

  // Pipeline State (Pre-fetching)
  const [prefetchedAnswerAudio, setPrefetchedAnswerAudio] = useState<string | null>(null);
  const [prefetchedNextQuestion, setPrefetchedNextQuestion] = useState<TriviaQuestion | null>(null);
  const [isPrefetchingQuestion, setIsPrefetchingQuestion] = useState<boolean>(false);

  // History and Results
  const [lastTurnResult, setLastTurnResult] = useState<LastTurnResult | null>(null);
  const [history, setHistory] = useState<string[]>([]);
  const [customGenreInput, setCustomGenreInput] = useState<string>('');

  // Audio / Refs
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioRequestIdRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const stopAudio = () => {
    audioRequestIdRef.current += 1;
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.onended = null;
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
  };

  const decodePCM = (base64Data: string, ctx: AudioContext): AudioBuffer => {
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const pcm16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, pcm16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < pcm16.length; i++) channelData[i] = pcm16[i] / 32768.0;
    return buffer;
  };

  const playAudio = (base64Data: string, onEnded?: () => void): void => {
    if (isMuted) {
      onEnded?.();
      return;
    }
    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') ctx.resume();
      stopAudio();
      const buffer = decodePCM(base64Data, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        currentSourceRef.current = null;
        onEnded?.();
      };
      source.start(0);
      currentSourceRef.current = source;
    } catch (e) {
      console.error("Playback error", e);
      onEnded?.();
    }
  };

  const fetchQuestionData = async (targetDifficulty: Difficulty, targetGenre: string, hist: string[]) => {
    try {
      const newQuestion = await generateTriviaQuestion(targetGenre, targetDifficulty, hist);
      return newQuestion;
    } catch (error) {
      console.error("Failed to fetch question", error);
      return null;
    }
  };

  const prefetchAnswerAudio = useCallback(async (correctAnswer: string, explanation: string) => {
    if (isMuted) return;
    const text = `${correctAnswer}. ${explanation}`;
    const audioData = await generateTriviaAudio(text);
    if (audioData) setPrefetchedAnswerAudio(audioData);
  }, [isMuted]);

  const applyQuestion = useCallback((q: TriviaQuestion) => {
    setQuestion(q);
    setUserAnswer('');
    setIsAnswerRevealed(false);
    setIsCorrect(false);
    setPrefetchedAnswerAudio(null);
    setLoading(false);

    if (q && q.questionText && !q.questionText.includes("Error")) {
      setHistory(prev => {
        const newHist = [q.questionText, ...prev].slice(0, 50);
        localStorage.setItem('trivia_history', JSON.stringify(newHist));
        return newHist;
      });
      prefetchAnswerAudio(q.correctAnswer, q.explanation);
    }
  }, [prefetchAnswerAudio]);

  const startGame = async (selectedGenre: string) => {
    getAudioContext();
    setGenre(selectedGenre);
    setDifficulty(Difficulty.EASY);
    setGameState(GameState.PLAYING);
    setLoading(true);
    setQuestion(null);
    setPrefetchedNextQuestion(null);

    const q = await fetchQuestionData(Difficulty.EASY, selectedGenre, history);
    if (q) applyQuestion(q);
    else setLoading(false);
  };

  const getNextDifficulty = (current: Difficulty, correct: boolean): Difficulty | 'VICTORY' => {
    if (correct) {
      if (current === Difficulty.EASY) return Difficulty.MEDIUM;
      if (current === Difficulty.MEDIUM) return Difficulty.HARD;
      return 'VICTORY';
    } else {
      if (current === Difficulty.HARD) return Difficulty.MEDIUM;
      return Difficulty.EASY;
    }
  };

  const triggerNextQuestionPrefetch = async (nextDiff: Difficulty | 'VICTORY', currentGenre: string) => {
    if (nextDiff === 'VICTORY') return;
    setIsPrefetchingQuestion(true);
    const q = await fetchQuestionData(nextDiff, currentGenre, history);
    setPrefetchedNextQuestion(q);
    setIsPrefetchingQuestion(false);
  };

  const checkAndApplyNextQuestion = useCallback(() => {
    if (prefetchedNextQuestion) {
      applyQuestion(prefetchedNextQuestion);
      setPrefetchedNextQuestion(null);
    } else {
      setQuestion(null); // Clear old question to show loading spinner
      setLoading(true);
    }
  }, [prefetchedNextQuestion, applyQuestion]);

  const handleSubmitAnswer = async () => {
    if (isAnswerRevealed || !question || !userAnswer.trim()) return;

    setLastTurnResult(null);
    stopAudio(); 
    setIsAnswerRevealed(true);

    const normalizedUserAnswer = userAnswer.toLowerCase().trim().replace(/^(the|a|an)\s+/i, "").replace(/[^\w\s]/gi, "");
    const match = question.acceptedAnswers.some(ans => {
      const norm = ans.toLowerCase().trim().replace(/^(the|a|an)\s+/i, "").replace(/[^\w\s]/gi, "");
      return norm === normalizedUserAnswer;
    });

    setIsCorrect(match);
    const nextDiff = getNextDifficulty(difficulty, match);

    if (nextDiff !== 'VICTORY') {
      triggerNextQuestionPrefetch(nextDiff, genre);
    }

    const playAndProceed = (audio: string) => {
      playAudio(audio, () => {
        setTimeout(() => {
          setLastTurnResult({
            isCorrect: match,
            correctAnswer: question.correctAnswer,
            explanation: question.explanation
          });

          if (nextDiff === 'VICTORY') {
            setGameState(GameState.VICTORY);
          } else {
            setDifficulty(nextDiff);
            // Hide the lower feedback panel before checkAndApply
            setIsAnswerRevealed(false);
            checkAndApplyNextQuestion();
          }
        }, 800);
      });
    };

    if (prefetchedAnswerAudio) {
      playAndProceed(prefetchedAnswerAudio);
    } else {
      const text = `${question.correctAnswer}. ${question.explanation}`;
      const freshAudio = await generateTriviaAudio(text);
      if (freshAudio) playAndProceed(freshAudio);
      else playAndProceed(""); 
    }
  };

  useEffect(() => {
    // If we are in loading state and the prefetched question arrives, apply it immediately.
    if (loading && prefetchedNextQuestion) {
      applyQuestion(prefetchedNextQuestion);
      setPrefetchedNextQuestion(null);
    }
  }, [loading, prefetchedNextQuestion, applyQuestion]);

  useEffect(() => {
    if (question && gameState === GameState.PLAYING && !isAnswerRevealed && !loading) {
      const timer = setTimeout(() => {
        const requestId = ++audioRequestIdRef.current;
        generateTriviaAudio(question.questionText).then(audio => {
          if (requestId === audioRequestIdRef.current && audio) {
            playAudio(audio);
          }
        });
        if (inputRef.current) inputRef.current.focus();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [question, gameState, isAnswerRevealed, loading]);

  const restartGame = () => {
    stopAudio();
    setGameState(GameState.WELCOME);
    setDifficulty(Difficulty.EASY);
    setQuestion(null);
    setPrefetchedNextQuestion(null);
    setLastTurnResult(null);
  };

  return (
    <div className="relative w-full min-h-screen font-sans bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-950/40 via-slate-950 to-slate-950"></div>
        <div className="absolute top-[-10%] right-[-10%] w-[600px] h-[600px] rounded-full bg-indigo-600/10 blur-[120px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] rounded-full bg-purple-600/10 blur-[120px]"></div>
      </div>

      {gameState === GameState.WELCOME && (
        <div className="flex flex-col items-center justify-center min-h-screen p-6 pb-32 text-center max-w-4xl mx-auto z-10 relative">
          <div className="mb-12 space-y-4 animate-[fadeIn_0.8s_ease-out]">
            <h1 className="text-7xl md:text-9xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-slate-500 drop-shadow-2xl">
              ASCENSION
            </h1>
            <p className="text-xl text-slate-400 font-medium tracking-widest uppercase opacity-80">
              Wikipedia Research Engine • Trivia Mode
            </p>
          </div>

          <div className="w-full glass-panel p-10 rounded-[2.5rem] shadow-2xl border-white/5 animate-[slideUp_0.6s_ease-out]">
            <h2 className="text-2xl font-bold mb-8 text-white/90">Choose Your Realm of Inquiry</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
              {GENRES.map((g) => (
                <button key={g} onClick={() => startGame(g)} className="group relative p-5 rounded-2xl bg-white/5 hover:bg-white/10 border border-white/5 hover:border-indigo-500/50 transition-all duration-300">
                  <span className="relative z-10 font-semibold text-slate-300 group-hover:text-white">{g}</span>
                </button>
              ))}
              <button onClick={() => startGame("General Knowledge")} className="col-span-2 md:col-span-4 mt-2 p-5 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold tracking-widest shadow-xl transition-all active:scale-95">
                RANDOM RESEARCH
              </button>
            </div>

            <div className="pt-8 border-t border-white/5">
              <div className="flex flex-col md:flex-row gap-3">
                <input type="text" value={customGenreInput} onChange={(e) => setCustomGenreInput(e.target.value)} placeholder="Specific Topic (e.g. Renaissance Art, 90s Games)" className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 transition-all" onKeyDown={(e) => e.key === 'Enter' && customGenreInput.trim() && startGame(customGenreInput)} />
                <Button onClick={() => startGame(customGenreInput)} disabled={!customGenreInput.trim()} className="px-10 rounded-2xl">Start</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.PLAYING && (
        <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 max-w-3xl mx-auto w-full relative z-10">
          <div className="w-full flex justify-between items-center mb-6 bg-white/5 backdrop-blur-xl p-4 rounded-3xl border border-white/10">
            <button onClick={restartGame} className="text-sm font-bold text-slate-500 hover:text-white transition-colors flex items-center gap-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
              ABORT
            </button>
            <div className="flex items-center gap-4">
              <button onClick={() => setIsMuted(!isMuted)} className={`p-2.5 rounded-full ${isMuted ? 'text-slate-600' : 'text-indigo-400 bg-indigo-400/10'}`}>
                {isMuted ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" /></svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                )}
              </button>
              <DifficultyBadge difficulty={difficulty} />
            </div>
          </div>

          {lastTurnResult && (
            <div className={`w-full mb-6 p-6 rounded-3xl border animate-[fadeIn_0.5s_ease-out] backdrop-blur-md ${lastTurnResult.isCorrect ? "bg-emerald-500/5 border-emerald-500/20" : "bg-rose-500/5 border-rose-500/20"}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`w-2 h-2 rounded-full ${lastTurnResult.isCorrect ? "bg-emerald-400" : "bg-rose-400"}`}></div>
                <span className={`font-bold text-xs uppercase tracking-[0.2em] ${lastTurnResult.isCorrect ? "text-emerald-400" : "text-rose-400"}`}>
                  {lastTurnResult.isCorrect ? "Validated" : "Incorrect"}
                </span>
                <span className="text-white/20">|</span>
                <span className="text-slate-300 text-sm font-medium">ANSWER: <span className="text-white font-bold">{lastTurnResult.correctAnswer}</span></span>
              </div>
              <p className="text-slate-400 text-sm leading-relaxed italic">"{lastTurnResult.explanation}"</p>
            </div>
          )}

          {loading ? (
            <div className="flex flex-col items-center py-20">
              <LoadingSpinner />
              <p className="mt-4 text-xs font-bold tracking-[0.3em] text-indigo-500/60 uppercase animate-pulse">Researching Next Subject</p>
            </div>
          ) : question ? (
            <div className="w-full space-y-6 animate-[fadeIn_0.4s_ease-out]">
              <div className="glass-panel p-10 rounded-[3rem] shadow-2xl relative overflow-hidden border-white/5">
                <div className="absolute top-0 left-0 h-1.5 w-full bg-white/5">
                  <div className={`h-full transition-all duration-1000 ${difficulty === Difficulty.HARD ? 'bg-rose-500' : difficulty === Difficulty.MEDIUM ? 'bg-amber-400' : 'bg-emerald-400'}`} style={{ width: difficulty === Difficulty.HARD ? '100%' : difficulty === Difficulty.MEDIUM ? '66%' : '33%' }}></div>
                </div>
                <div className="mb-4"><span className="text-xs font-black tracking-[0.3em] text-indigo-400/80 uppercase">{genre}</span></div>
                <h2 className="text-2xl md:text-4xl font-bold text-white leading-[1.2] mb-10">{question.questionText}</h2>
                <div className="flex flex-col md:flex-row gap-4">
                  <input ref={inputRef} type="text" value={userAnswer} onChange={(e) => !isAnswerRevealed && setUserAnswer(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSubmitAnswer()} disabled={isAnswerRevealed} placeholder="Type answer..." className={`flex-1 bg-white/5 border-2 rounded-2xl px-6 py-5 text-xl text-white focus:outline-none transition-all ${isAnswerRevealed ? (isCorrect ? 'border-emerald-500/50 bg-emerald-500/5' : 'border-rose-500/50 bg-rose-500/5') : 'border-white/10 focus:border-indigo-500'}`} />
                  <Button onClick={handleSubmitAnswer} disabled={!userAnswer.trim() || isAnswerRevealed} className="px-10 text-lg">SUBMIT</Button>
                </div>
              </div>

              {isAnswerRevealed && (
                <div className={`p-8 rounded-[2.5rem] glass-panel border-l-4 transition-all duration-500 ${isCorrect ? 'border-emerald-500 shadow-[0_0_30px_rgba(16,185,129,0.1)]' : 'border-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.1)]'}`}>
                  <div className="flex items-center gap-4 mb-4">
                    <span className={`text-sm font-black tracking-widest uppercase ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}`}>{isCorrect ? 'Verified' : 'Incorrect'}</span>
                    {!isCorrect && <span className="text-slate-300 font-medium">Correct: <span className="text-white font-bold">{question.correctAnswer}</span></span>}
                  </div>
                  <p className="text-lg text-slate-200 leading-relaxed font-medium">{question.explanation}</p>
                  <div className="mt-8 flex items-center gap-3">
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    </div>
                    <span className="text-[10px] font-black tracking-[0.3em] text-indigo-500/60 uppercase">System Syncing Next Subject</span>
                  </div>
                </div>
              )}
            </div>
          ) : null}
        </div>
      )}

      {gameState === GameState.VICTORY && (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center z-10 relative">
          <div className="glass-panel p-16 rounded-[4rem] shadow-2xl max-w-2xl border-white/5 animate-[zoomIn_0.5s_ease-out]">
            <div className="mb-6 inline-block p-4 rounded-full bg-emerald-500/20 text-emerald-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 13l4 4L19 7" /></svg>
            </div>
            <h1 className="text-7xl font-black text-white mb-4">ASCENDED</h1>
            <p className="text-xl text-slate-400 mb-12">You have mastered the domain of {genre}.</p>
            <Button onClick={restartGame} className="px-12 py-5 text-xl rounded-2xl shadow-indigo-500/40">BEGIN NEW ASCENSION</Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { Difficulty, TriviaQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questionText: {
      type: Type.STRING,
      description: "The trivia question text sourced from a Wikipedia-style fact."
    },
    acceptedAnswers: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of valid answers including variations with/without articles and abbreviations.",
    },
    correctAnswer: {
      type: Type.STRING,
      description: "The primary correct answer.",
    },
    explanation: {
      type: Type.STRING,
      description: "Exactly one concise sentence containing an interesting fact explaining the answer.",
    }
  },
  required: ["questionText", "acceptedAnswers", "correctAnswer", "explanation"],
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateTriviaQuestion = async (
  genre: string, 
  difficulty: Difficulty, 
  previousQuestions: string[] = []
): Promise<TriviaQuestion> => {
  const model = "gemini-3-flash-preview";

  const prompt = `
    Use Google Search to find Wikipedia articles related to "${genre}". 
    From those articles, find an interesting, verifiable fact to create a ${difficulty.toLowerCase()} difficulty trivia question.

    RESEARCH TARGET: Focus on a specific sub-topic or person within "${genre}" to ensure high variety.

    Difficulty Guidelines:
    - Easy: General, well-known facts found in the intro of popular articles.
    - Medium: Facts from middle sections of articles, requiring some depth.
    - Hard: Obscure details, niche figures, or specific dates/names from deep within Wikipedia.

    Constraints:
    - The answer must be 1-4 words.
    - The explanation MUST be exactly one concise sentence long.
    - Provide 5-10 variations in 'acceptedAnswers'. Include versions with and without articles (a, an, the).
    - AVOID REPETITION: Do not use facts similar to these: ${JSON.stringify(previousQuestions.slice(0, 10))}.
    - Ensure the question is sourced from real-world data found via search.
  `;

  let lastError: any;

  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: questionSchema,
          temperature: 1.0, 
          tools: [{ googleSearch: {} }]
        },
      });

      const text = response.text;
      if (!text) throw new Error("Empty response from Gemini");

      return JSON.parse(text) as TriviaQuestion;
    } catch (error: any) {
      console.error(`Attempt ${attempt} failed:`, error);
      lastError = error;
      if (attempt < 3) await delay(1500 * attempt);
    }
  }

  return {
    questionText: `System Error: ${lastError?.message || "Connectivity issue"}. Type 'retry' to continue.`,
    acceptedAnswers: ["retry"],
    correctAnswer: "retry",
    explanation: "I encountered a technical hurdle while researching. Let's try once more."
  };
};

export const generateTriviaAudio = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Fenrir' },
            },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (error) {
    console.error("Audio generation failed:", error);
    return null;
  }
};
